{
  "name": "frontend",
  "private": true,
  "version": "0.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "tsc -b && vite build",
    "lint": "eslint .",
    "preview": "vite preview"
  },
  "dependencies": {
    "react": "^19.2.6",
    "react-dom": "^19.2.6"
  },
  "devDependencies": {
    "@eslint/js": "^10.0.1",
    "@types/node": "^24.12.3",
    "@types/react": "^19.2.14",
    "@types/react-dom": "^19.2.3",
    "@vitejs/plugin-react": "^6.0.1",
    "eslint": "^10.3.0",
    "eslint-plugin-react-hooks": "^7.1.1",
    "eslint-plugin-react-refresh": "^0.5.2",
    "globals": "^17.6.0",
    "typescript": "~6.0.2",
    "typescript-eslint": "^8.59.2",
    "vite": "^8.0.12"
  }
}
import type { ReactNode } from 'react'

export function AppShell({ children }: { children: ReactNode }) {
  return (
    <div className="app-shell">
      <div className="brand">
        <span className="brand-mark" aria-hidden="true"><FrameIcon /></span>
        <span className="brand-name">Global Inventory<small>Frames Â· OOH</small></span>
      </div>
      <header className="topbar">
        <span>Inventory</span><span className="breadcrumb-separator" aria-hidden="true">/</span>
        <span className="breadcrumb-current">Frames</span>
      </header>
      <nav className="rail" aria-label="Primary navigation">
        <div className="rail-label">Inventory</div>
        <div className="nav-item" aria-current="page"><FrameIcon /> Frames</div>
      </nav>
      <main className="content">{children}</main>
    </div>
  )
}

function FrameIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"
      strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <rect x="3" y="5" width="18" height="14" rx="1" /><path d="M3 9h18" />
    </svg>
  )
}
import type { FrameFilters as FrameFilterValues } from '../api/frames'

type Props = {
  query: string
  filters: FrameFilterValues
  onQueryChange: (value: string) => void
  onFilterChange: <K extends keyof FrameFilterValues>(name: K, value: FrameFilterValues[K]) => void
  onClear: () => void
}

export function FrameFilters({ query, filters, onQueryChange, onFilterChange, onClear }: Props) {
  const hasFilters = Boolean(
    query.trim() || filters.status || filters.mediaType.trim() ||
    filters.environment.trim() || filters.format.trim() || filters.region.trim(),
  )

  return (
    <aside className="filters" aria-label="Frame filters">
      <div className="filters-header">
        <h2>Filter frames</h2>
        {hasFilters && <button className="button button-link" type="button" onClick={onClear}>Clear all</button>}
      </div>
      <div className="filter-list">
        <div className="field">
          <label htmlFor="frame-search">Search</label>
          <input id="frame-search" className="input search-input" type="search" value={query}
            placeholder="ID, site or location" onChange={(event) => onQueryChange(event.target.value)} />
        </div>
        <div className="field">
          <label htmlFor="status-filter">Status</label>
          <select id="status-filter" className="select" value={filters.status}
            onChange={(event) => onFilterChange('status', event.target.value as FrameFilterValues['status'])}>
            <option value="">All</option><option value="LIVE">LIVE</option><option value="INACTIVE">INACTIVE</option>
          </select>
        </div>
        <StringFilter id="media-type-filter" label="Media type" value={filters.mediaType}
          onChange={(value) => onFilterChange('mediaType', value)} />
        <StringFilter id="environment-filter" label="Environment" value={filters.environment}
          onChange={(value) => onFilterChange('environment', value)} />
        <StringFilter id="format-filter" label="Format" value={filters.format}
          onChange={(value) => onFilterChange('format', value)} />
        <StringFilter id="region-filter" label="Region" value={filters.region}
          onChange={(value) => onFilterChange('region', value)} />
      </div>
    </aside>
  )
}

function StringFilter({ id, label, value, onChange }: {
  id: string; label: string; value: string; onChange: (value: string) => void
}) {
  return (
    <div className="field">
      <label htmlFor={id}>{label}</label>
      <input id={id} className="input" type="text" value={value} placeholder="All"
        onChange={(event) => onChange(event.target.value)} />
    </div>
  )
}
import './App.css'
import { AppShell } from './components/AppShell'
import { InventoryPage } from './components/InventoryPage'

function App() {
  return (
    <AppShell>
      <InventoryPage />
    </AppShell>
  )
}

export default App
@import './styles/tokens.css';

*, *::before, *::after { box-sizing: border-box; }

:root {
  font-family: var(--font-sans);
  color: var(--text-primary);
  background: var(--bg-subtle);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

html, body, #root { min-width: 320px; min-height: 100%; margin: 0; }
body { min-height: 100vh; }
button, input, select { font-family: inherit; }

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
