export type FrameSummary = {
  frameId: string
  mediaType: string
  format: string
  environment: string | null
  status: string
  modifiedDate: string
  address: string | null
  town: string | null
  region: string | null
  station: string | null
  airport: string | null
}

export type FramePage = {
  items: FrameSummary[]
  page: number
  size: number
  totalElements: number
  totalPages: number
}

export type FrameFilters = {
  status: '' | 'LIVE' | 'INACTIVE'
  mediaType: string
  environment: string
  format: string
  region: string
}

export type GetFramesParams = FrameFilters & { page: number; size: number; q: string }
type ProblemDetail = { title?: string; detail?: string }

export class FrameApiError extends Error {
  status: number

  constructor(message: string, status: number) {
    super(message)
    this.name = 'FrameApiError'
    this.status = status
  }
}

export async function getFrames(
  params: GetFramesParams,
  signal?: AbortSignal,
): Promise<FramePage> {
  const searchParams = new URLSearchParams({ page: String(params.page), size: String(params.size) })
  addIfPresent(searchParams, 'q', params.q)
  addIfPresent(searchParams, 'status', params.status)
  addIfPresent(searchParams, 'mediaType', params.mediaType)
  addIfPresent(searchParams, 'environment', params.environment)
  addIfPresent(searchParams, 'format', params.format)
  addIfPresent(searchParams, 'region', params.region)

  const response = await fetch(`/api/frames?${searchParams.toString()}`, {
    headers: { Accept: 'application/json' },
    signal,
  })
  if (!response.ok) throw new FrameApiError(await readErrorMessage(response), response.status)
  return (await response.json()) as FramePage
}

function addIfPresent(params: URLSearchParams, key: string, value: string) {
  const normalizedValue = value.trim()
  if (normalizedValue) params.set(key, normalizedValue)
}

async function readErrorMessage(response: Response): Promise<string> {
  try {
    const problem = (await response.json()) as ProblemDetail
    return problem.detail || problem.title || `Request failed with status ${response.status}`
  } catch {
    return `Request failed with status ${response.status}`
  }
}
import type { FrameFilters as FrameFilterValues } from '../api/frames'

type Props = {
  query: string
  filters: FrameFilterValues
  onQueryChange: (value: string) => void
  onFilterChange: <K extends keyof FrameFilterValues>(name: K, value: FrameFilterValues[K]) => void
  onClear: () => void
}

export function FrameFilters({ query, filters, onQueryChange, onFilterChange, onClear }: Props) {
  const hasFilters = Boolean(
    query.trim() || filters.status || filters.mediaType.trim() ||
    filters.environment.trim() || filters.format.trim() || filters.region.trim(),
  )

  return (
    <aside className="filters" aria-label="Frame filters">
      <div className="filters-header">
        <h2>Filter frames</h2>
      </div>
      <div className="filter-search">
        <div className="field">
          <label htmlFor="frame-search">Search</label>
          <input id="frame-search" className="input search-input" type="search" value={query}
            placeholder="ID, site or location" onChange={(event) => onQueryChange(event.target.value)} />
        </div>
      </div>
      <div className="filter-controls">
        <div className="field">
          <label htmlFor="status-filter">Status</label>
          <select id="status-filter" className="select" value={filters.status}
            onChange={(event) => onFilterChange('status', event.target.value as FrameFilterValues['status'])}>
            <option value="">All</option><option value="LIVE">LIVE</option><option value="INACTIVE">INACTIVE</option>
          </select>
        </div>
        <StringFilter id="media-type-filter" label="Media type" value={filters.mediaType}
          onChange={(value) => onFilterChange('mediaType', value)} />
        <StringFilter id="environment-filter" label="Environment" value={filters.environment}
          onChange={(value) => onFilterChange('environment', value)} />
        <StringFilter id="format-filter" label="Format" value={filters.format}
          onChange={(value) => onFilterChange('format', value)} />
        <StringFilter id="region-filter" label="Region" value={filters.region}
          onChange={(value) => onFilterChange('region', value)} />
        {hasFilters && <button className="button button-link clear-filters" type="button" onClick={onClear}>Clear all</button>}
      </div>
    </aside>
  )
}

function StringFilter({ id, label, value, onChange }: {
  id: string; label: string; value: string; onChange: (value: string) => void
}) {
  return (
    <div className="field">
      <label htmlFor={id}>{label}</label>
      <input id={id} className="input" type="text" value={value} placeholder="All"
